head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > E > onafterblur]<br/>Textarea 컴포넌트에서 포커스가 사라진 후 내부 처리가 완료되면 발생합니다.",
    "validation" : [
        "Textarea 컴포넌트에서 포커스가 사라진 후 내부 처리가 완료되면 onafterblur 이벤트가 발생합니다.",
        "이벤트 객체 e (FocusEvent) 가 핸들러에 전달됩니다.",
        "값 변경이 있는 경우 'onblur -> onchange -> onviewchange -> onafterblur' 순서로 이벤트가 발생합니다.",
        "값 변경이 없는 경우 'onblur -> onafterblur' 순서로 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        readOnly: con_readOnly.getText(),
    }

    let cList = $c.gcm.createCList(properties)
    let eList = $c.gcm.createEList(["onblur", "onchange", "onviewchange", "onafterblur"])

    // comp 생성 함수 호출
    $c.gcm.createBasicTextArea(cList, eList);
}



scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onblur 이벤트 발생=====");
}

scwin.target1_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange 이벤트 발생=====");
}

scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange 이벤트 발생=====");
}

scwin.target1_onafterblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onafterblur 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
}
